import type { ContentBlockManifestEntry } from './contentBlocks.js'

// Hand-authored, NOT generated by scripts/scanVariables.mjs — same reasoning as
// coverFields.ts: these keys back Page 02 component props/module-level consts
// (heading/subtitle/welcomeHeading/introParagraph/companyDescription), not
// literal JSX text, so the scanner structurally can't see them. Shaped
// identically to ContentBlockManifestEntry so the Editor's existing
// click-to-edit / contentOverride / undo / autosave pipeline needs zero
// changes to support them — see ProposalEditor.tsx.
//
// "Welcome, [Client First Name]" keeps its bracket placeholder as-is in the
// default text — applyVariables() (already wired into resolveContentBlockText)
// resolves it automatically from the document's `clientFirstName` variable,
// exactly like Cover's description resolves "[Client Name]". No new
// substitution logic needed.

const DEFAULT_INTRO =
  'Most founders find out their revenue process is broken when the numbers stop adding up. By then it has already cost them deals.'

const DEFAULT_COMPANY =
  'Novara is a RevOps consultancy built for founders who need their sales and marketing systems working as one, not bolted together. We get inside the pipeline, find where revenue is leaking, and fix it.\n\nStrategy, systems, and execution sit under one roof. No handoffs. No agency relay race. Everything is owned and delivered in the UK, directly by us.'

export function getPage02FieldEntries(): ContentBlockManifestEntry[] {
  return [
    { key: 'page02.heading', page: 'page02', originalText: 'Who We Are', label: 'Main Heading', variants: ['both'] },
    {
      key: 'page02.subtitle',
      page: 'page02',
      originalText: 'A RevOps consultancy that gets inside your pipeline, not just your slide deck.',
      label: 'Subtitle',
      variants: ['both'],
    },
    {
      key: 'page02.welcomeHeading',
      page: 'page02',
      originalText: 'Welcome, [Client First Name]',
      label: 'Welcome Heading',
      variants: ['both'],
    },
    { key: 'page02.introParagraph', page: 'page02', originalText: DEFAULT_INTRO, label: 'Intro Paragraph', variants: ['both'] },
    {
      key: 'page02.companyDescription',
      page: 'page02',
      originalText: DEFAULT_COMPANY,
      label: 'Company Description',
      variants: ['both'],
    },
  ]
}
